const fs=require('fs');
const combined=fs.readFileSync('SMS_Broadcast_All_Modules.txt','utf8');
const modules=['MainMacro.bas','Helpers.bas','ConfigReader.bas','CaseMatcher.bas','BroadcastBuilder.bas'];
for (const m of modules) {
  if (fs.existsSync(m)) {
    const src=fs.readFileSync(m,'utf8');
    const startMarker='Attribute VB_Name = \"'+m.replace('.bas','')+'\"';
    const start=combined.indexOf(startMarker);
    if (start<0){ console.log(m,'NOT FOUND in combined'); continue; }
    const end=start+src.length;
    const section=combined.slice(start,end);
    console.log(m, 'match:', section===src, 'src len', src.length);
  }
}
